//! DiffusionGemma (`diffusion_gemma`, mlx-community's layout): the claim and the parse. The trunk is Gemma 4 26B-A4B
//! (the shared Gemma `Config`, prefix `model.decoder`, K=V full layers) generated by block diffusion: the canvas
//! facts come from `canvas_length` and the embedded `generation_config`. MLX-free. The image tower under
//! `model.encoder` is not served (text only, as the engine).

const std = @import("std");
const abi = @import("../../abi/plugin.zig");
const sdk = @import("../../sdk/root.zig");
const generation = @import("../../sdk/config/generation.zig");
const gemma = @import("../gemma3/config.zig");

pub const model_types = [_][]const u8{"diffusion_gemma"};

pub const claims = sdk.claimsByType(&model_types);

pub const Config = gemma.Config;
pub const unsupported = gemma.unsupported;
pub const freeParsed = gemma.freeParsed;
pub const of = gemma.of;
pub const layout = gemma.layout;
const field = gemma.field;

pub fn parse(dir: *const abi.PackDir, config_json: abi.Str, settings_json: abi.Str, span: ?*const abi.LayerSpan, stub: bool, out: *abi.Parsed) callconv(.c) abi.Verdict {
    _ = settings_json;
    var d: gemma.Doc = undefined;
    const opened = gemma.Doc.open(config_json, &d);
    if (!opened.isOk()) return opened;
    defer d.close();
    if (span != null) return unsupported("a layer span (the cluster split)");
    if (!std.mem.eql(u8, d.model_type, "diffusion_gemma")) return unsupported("another model_type");
    if (gemma.foreignQuant(d.root)) return unsupported("a quantization_config naming a quant_method");

    var c: Config = .{};
    gemma.readCommon(d.root, d.cfg, &c) catch return unsupported("a field out of range");
    gemma.readQuant(d.root, &c) catch return unsupported("quantization");
    // The engine's DiffusionGemma arm: Gemma 4's traits under `model.decoder`, V = the normed k_proj on full layers.
    c.model_type = "diffusion_gemma";
    c.weight_prefix = "model.decoder";
    c.norm_has_offset = false;
    c.has_v_norm = true;
    c.rope_scaling_factor = 1.0;
    c.attention_k_eq_v = true;
    if (c.num_experts == 0 or c.num_experts_per_tok == 0 or c.num_experts_per_tok > c.num_experts or c.moe_intermediate_size == 0)
        return unsupported("a trunk without experts");
    if (c.hidden_size_per_layer_input > 0 or c.num_kv_shared_layers > 0) return unsupported("per-layer inputs or KV sharing");
    if (c.vocab_size == 0 or c.vocab_size > 1 << 22 or c.hidden_size == 0 or c.hidden_size > 1 << 16 or
        c.num_hidden_layers == 0 or c.num_hidden_layers > gemma.max_layer_types or c.num_attention_heads == 0 or
        c.num_key_value_heads == 0 or c.intermediate_size == 0 or c.head_dim == 0 or c.head_dim % 2 != 0 or
        c.head_dim > 512 or c.global_head_dim > 512 or c.global_head_dim % 2 != 0 or
        (c.has_sliding_window and c.sliding_window_pattern == 0) or
        c.partial_rotary_factor_global <= 0 or c.partial_rotary_factor_global > 1)
        return unsupported("dimensions out of range");

    var canvas: abi.CanvasFacts = .{ .length = 256 };
    readCanvas(d.root, &canvas) catch return unsupported("a canvas field out of range");
    const v = gemma.finish(dir, d.root, c, stub, .{ .block_diffusion = true, .moe = true, .prefix_cache = false }, out);
    if (!v.isOk()) return v;
    out.canvas = canvas;
    // No top-level stop set: the embedded generation_config's, then the Gemma terminators, as the engine merges.
    if (field(d.root, "eos_token_id") == null) if (field(d.root, "generation_config")) |gc| if (gc == .object) if (field(gc.object, "eos_token_id")) |e| {
        const s = &out.shell;
        s.eos_count = 0;
        switch (e) {
            .integer => generation.addEos(s, gemma.int(e) catch return unsupported("eos_token_id")),
            .array => |arr| for (arr.items) |item| if (item == .integer) generation.addEos(s, gemma.int(item) catch return unsupported("eos_token_id")),
            else => {},
        }
        for (gemma.terminators) |t| generation.mergeEos(s, t);
    };
    return .ok;
}

/// `canvas_length` (top level) and the denoising knobs of the embedded `generation_config`.
fn readCanvas(root: std.json.ObjectMap, cv: *abi.CanvasFacts) error{Unsupported}!void {
    if (field(root, "canvas_length")) |v| if (v == .integer) {
        cv.length = try gemma.int(v);
    };
    if (cv.length == 0) cv.length = 256;
    const gc_val = field(root, "generation_config") orelse return;
    if (gc_val != .object) return;
    const gc = gc_val.object;
    if (field(gc, "max_denoising_steps")) |v| if (v == .integer) {
        cv.max_steps = try gemma.int(v);
    };
    if (field(gc, "t_min")) |v| cv.t_min = try gemma.float(v);
    if (field(gc, "t_max")) |v| cv.t_max = try gemma.float(v);
    if (field(gc, "confidence_threshold")) |v| cv.confidence_threshold = try gemma.float(v);
    if (field(gc, "stability_threshold")) |v| if (v == .integer) {
        cv.stability_threshold = try gemma.int(v);
    };
    if (field(gc, "pad_token_id")) |v| if (v == .integer) {
        cv.pad_token = try gemma.int(v);
    };
    if (field(gc, "sampler_config")) |sc| if (sc == .object) if (field(sc.object, "entropy_bound")) |v| {
        cv.entropy_bound = try gemma.float(v);
    };
}

// ── tests ──

const testing = std.testing;
const fixture = sdk.fixture;

fn parseJson(json: []const u8, out: *abi.Parsed) abi.Verdict {
    const mem: fixture.MemDir = .{ .files = &.{.{ .name = "config.json", .bytes = json }} };
    const dir = mem.packDir();
    return parse(&dir, abi.Str.of(json), .{}, null, true, out);
}

test "diffusion_gemma config: the canvas facts, the trunk's experts and K=V, the stop set from generation_config" {
    const json =
        \\{"model_type":"diffusion_gemma","canvas_length":128,"generation_config":{"confidence_threshold":0.01,
        \\"max_denoising_steps":32,"pad_token_id":0,"sampler_config":{"entropy_bound":0.2},"stability_threshold":2,
        \\"t_max":0.9,"t_min":0.3,"eos_token_id":[1,106,50]},"text_config":{"model_type":"diffusion_gemma_text",
        \\"vocab_size":262144,"hidden_size":2816,"intermediate_size":2112,"moe_intermediate_size":704,"num_experts":128,
        \\"top_k_experts":8,"num_hidden_layers":6,"num_attention_heads":16,"num_key_value_heads":8,
        \\"num_global_key_value_heads":2,"head_dim":256,"global_head_dim":512,"final_logit_softcapping":30.0,
        \\"sliding_window":1024,"layer_types":["sliding_attention","sliding_attention","sliding_attention",
        \\"sliding_attention","sliding_attention","full_attention"],"rope_parameters":{"full_attention":
        \\{"partial_rotary_factor":0.25,"rope_theta":1000000.0,"rope_type":"proportional"},"sliding_attention":
        \\{"rope_theta":10000.0}}},"vision_config":{"hidden_size":1152},"quantization":{"group_size":64,"bits":4}}
    ;
    var p: abi.Parsed = .{};
    try testing.expect(parseJson(json, &p).isOk());
    defer freeParsed(&p);
    try testing.expect(p.caps.block_diffusion and !p.caps.batches_decode and !p.caps.images);
    try testing.expectEqual(@as(u32, 128), p.canvas.length);
    try testing.expectEqual(@as(u32, 32), p.canvas.max_steps);
    try testing.expectEqual(@as(u32, 2), p.canvas.stability_threshold);
    try testing.expectApproxEqAbs(@as(f32, 0.2), p.canvas.entropy_bound, 1e-6);
    try testing.expectEqualSlices(u32, &.{ 1, 106, 50 }, p.shell.eos[0..p.shell.eos_count]);
    const c = of(&p);
    try testing.expect(c.attention_k_eq_v and c.has_v_norm and c.num_experts == 128);
    try testing.expectEqualStrings("model.decoder", c.weight_prefix);
}
